def solve_recurrence(x1, x2, max_n=5):
    """
    Calculates the sequence based on the recurrence relation and checks for integer values.
    x_{i+1} = (x_i^2 + 1) / (x_{i-1} + 1) - 1
    Returns the length of the valid integer sequence.
    """
    sequence = [x1, x2]

    for i in range(2, max_n):
        # Calculate x_{i+1} using x_i and x_{i-1}
        x_i = sequence[-1]
        x_i_minus_1 = sequence[-2]

        numerator = x_i**2 + 1
        denominator = x_i_minus_1 + 1

        if numerator % denominator != 0:
            # x_{i+1} is not an integer
            return len(sequence)

        x_next = (numerator // denominator) - 1

        if x_next <= 0:
            # x_i must be a positive integer
            return len(sequence)

        sequence.append(x_next)

    return len(sequence)

